"use client";
import { ArtemisScope } from "./artemis-scope";
import Variant0 from "./components/announcement-banners/variants/01-gradient-marquee";
import Variant1 from "./components/announcement-banners/variants/02-shader-launch";
import Variant2 from "./components/announcement-banners/variants/03-rotating-ribbon";
import Variant3 from "./components/announcement-banners/variants/04-stacked-cards";
const variants = {"gradient-marquee": Variant0,"shader-launch": Variant1,"rotating-ribbon": Variant2,"stacked-cards": Variant3};
export interface ArtemisAnnouncementBannersProps { className?: string; variant?: "gradient-marquee" | "shader-launch" | "rotating-ribbon" | "stacked-cards"; }
export function ArtemisAnnouncementBanners({ className, variant = "gradient-marquee" }: ArtemisAnnouncementBannersProps) { const View = variants[variant]; return <ArtemisScope className={`art:[&>*]:mx-auto ${className ?? ""}`}><View/></ArtemisScope>; }
